def parse_env_line(line):
    if not line or line.lstrip().startswith('#'):
        return None
    key, value = line.split('=')
    return key.strip(), value.strip()

files.test_parse_env_line.py:
import unittest
from parse_env_line import parse_env_line

class EnvLineTests(unittest.TestCase):
    def test_plain(self):
        self.assertEqual(parse_env_line('A=1'), ('A', '1'))
    def test_spaces_and_quotes(self):
        self.assertEqual(parse_env_line('B = "x y"'), ('B', 'x y'))
    def test_comment_and_blank(self):
        self.assertIsNone(parse_env_line('  # note'))
        self.assertIsNone(parse_env_line(''))
    def test_empty_value(self):
        self.assertEqual(parse_env_line('EMPTY='), ('EMPTY', ''))
    def test_no_equals(self):
        self.assertIsNone(parse_env_line('NO_EQUALS'))
    def test_value_with_equals(self):
        self.assertEqual(parse_env_line('TOKEN=a=b'), ('TOKEN', 'a=b'))

