import unittest
from merge_counts import merge_counts

class MergeTests(unittest.TestCase):
    def test_overlap_sums(self):
        self.assertEqual(merge_counts({'a': 2}, {'a': 3, 'b': 1}), {'a': 5, 'b': 1})
